 $title='מתכנן תקציב לנסיעה';$posted=$_SERVER['REQUEST_METHOD']==='POST';$rows=$posted&&is_array($_POST['rows']??null)?array_slice($_POST['rows'],0,15):array_map(fn($l)=>['label'=>$l,'amount'=>'','status'=>'missing','qty'=>1],$budgetLabels);$currency=in_array($_POST['currency']??'',['ILS','EUR','USD','GBP'],true)?$_POST['currency']:'ILS';$result=null;if($posted)try{foreach(['adults'=>[1,12,2],'children'=>[0,12,0],'nights'=>[1,60,4],'rooms'=>[1,8,1]] as $field=>$limits){if(filter_var($_POST[$field]??$limits[2],FILTER_VALIDATE_INT,['options'=>['min_range'=>$limits[0],'max_range'=>$limits[1]]])===false)throw new InvalidArgumentException('בדקו את מספר הנוסעים, החדרים והלילות.');}if(count($_POST['rows']??[])>15)throw new InvalidArgumentException('עד 15 סעיפים לתקציב.');$result=budget($rows);$result['travelers']=(int)($_POST['adults']??2)+(int)($_POST['children']??0);}catch(InvalidArgumentException $ex){$error=$ex->getMessage();}
 ?><section class="page-heading"><span class="eyebrow">כלי תכנון · 01</span><h1>כמה באמת תעלה החופשה?</h1><p>מזינים את הסכומים שמצאתם, מפרידים בין ידוע להערכה ומשאירים מקום למה שעוד חסר.</p></section><form method="post" id="budget-form" class="spacer-bottom"><?=csrf()?><section class="form-panel"><div class="fields"><label>מטבע החישוב<select name="currency"><?php foreach(['ILS'=>'₪ שקל','EUR'=>'€ אירו','USD'=>'$ דולר','GBP'=>'£ ליש״ט'] as $code=>$label):?><option value="<?=$code?>" <?=$currency===$code?'selected':''?>><?=$label?></option><?php endforeach?></select></label><label>מבוגרים<input type="number" name="adults" min="1" max="12" value="<?=e($_POST['adults']??2)?>"></label><label>ילדים<input type="number" name="children" min="0" max="12" value="<?=e($_POST['children']??0)?>"></label><label>לילות<input type="number" name="nights" min="1" max="60" value="<?=e($_POST['nights']??4)?>"></label><label>חדרים<input type="number" name="rooms" min="1" max="8" value="<?=e($_POST['rooms']??1)?>"></label></div><p class="notice">הסכומים הם לפי ההזנה שלכם, ללא בדיקת מחירים אצל ספק. כל הסעיפים באותו מטבע. הכמות בכל שורה היא המכפיל בפועל — עדכנו אותה לפי מספר האנשים, הלילות או היחידות.</p><div id="budget-rows"><?php foreach($rows as $i=>$row):?><div class="row-fields"><label>סעיף<input name="rows[<?=$i?>][label]" maxlength="60" value="<?=e($row['label']??'')?>"></label><label>מצב הסכום<select name="rows[<?=$i?>][status]"><?php foreach(['missing'=>'דרוש מידע','known'=>'סכום ידוע','estimate'=>'הערכה שלי','included'=>'כלול בחבילה הראשית','not_needed'=>'לא נדרש'] as $v=>$label):?><option value="<?=$v?>" <?=($row['status']??'missing')===$v?'selected':''?>><?=$label?></option><?php endforeach?></select></label><label>סכום ליחידה<input name="rows[<?=$i?>][amount]" inputmode="decimal" maxlength="11" value="<?=e($row['amount']??'')?>" placeholder="טרם הוזן"></label><label>כמות<input name="rows[<?=$i?>][qty]" type="number" min="1" max="1000" value="<?=e($row['qty']??1)?>"></label></div