?><section class="page-heading"><span class="eyebrow">כלי תכנון · 02</span><h1>שתי חבילות. תמונה אחת ברורה.</h1><p>השוו את אותם הפרטים, סמנו מה לא ידוע וגלו מה מסתתר מעבר למחיר הראשוני.</p></section><form method="post" id="compare-form" class="spacer-bottom"><?=csrf()?><div class="compare-grid"><?php foreach($packages as $i=>$p):?><section class="form-panel"><h2>אפשרות <?=$i===0?'א׳':'ב׳'?></h2><div class="fields"><?php foreach(['name'=>'כינוי לחבילה','provider'=>'ספק','destination'=>'יעד','room'=>'סוג חדר','board'=>'בסיס אירוח'] as $key=>$label):?><label><?=$label?><input name="packages[<?=$i?>][<?=$key?>]" value="<?=e($p[$key]??'')?>" maxlength="80"></label><?php endforeach?><label>מטבע<select name="packages[<?=$i?>][currency]"><?php foreach(['ILS','EUR','USD','GBP'] as $c):?><option <?=($p['currency']??'ILS')===$c?'selected':''?>><?=$c?></option><?php endforeach?></select></label><?php foreach(['departure'=>'תאריך יציאה','return'=>'תאריך חזרה'] as $key=>$label):?><label><?=$label?><input type="date" name="packages[<?=$i?>][<?=$key?>]" value="<?=e($p[$key]??'')?>"></label><?php endforeach?><?php foreach(['nights'=>['לילות',4,1,60],'adults'=>['מבוגרים',2,1,12],'children'=>['ילדים',0,0,12],'rooms'=>['חדרים',1,1,8]] as $key=>$x):?><label><?=$x[0]?><input type="number" name="packages[<?=$i?>][<?=$key?>]" min="<?=$x[2]?>" max="<?=$x[3]?>" value="<?=e($p[$key]??$x[1])?>"></label><?php endforeach?><?php foreach(['flight'=>'טיסה','baggage'=>'כבודה','transfer'=>'העברות'] as $key=>$label):?><label><?=$label?><select name="packages[<?=$i?>][<?=$key?>]"><?php foreach(['unknown'=>'לא ידוע','included'=>'כלול','extra'=>'בתשלום נוסף','not_relevant'=>'לא רלוונטי'] as $v=>$l):?><option value="<?=$v?>" <?=($p[$key]??'unknown')===$v?'selected':''?>><?=$l?></option><?php endforeach?></select></label><?php endforeach?><label>סוג טיסה<select name="packages[<?=$i?>][direct]"><?php foreach(['unknown'=>'לא ידוע','direct'=>'ישירה','stop'=>'עם עצירה'] as $v=>$l):?><option value="<?=$v?>" <?=